func:
// Passo de preparacao (idempotencia SEM apagar dados):
// identifica a recolha com uma chave natural e um marcador unico de execucao.
// A limpeza das recolhas antigas acontece SO no fim, depois de confirmar
// que os novos dados foram guardados.
msg.extraction_id = "open_meteo_ATL_2025-01";
msg.batch_ts = new Date().toISOString();
msg.meta = {
    source: "open_meteo",
    airport_code: "ATL",
    period: { start: "2025-01-01", end: "2025-01-31" },
    format: "json",
    endpoint: "https://archive-api.open-meteo.com/v1/archive",
    extracted_at: msg.batch_ts
};
return msg;

// Valida a resposta ANTES de tocar em qualquer colecao.
// Se falhar, aborta sem alterar nada; o ramo de erro regista em etl_logs.
const d = msg.payload;

if (!d || !d.hourly || !Array.isArray(d.hourly.time) || d.hourly.time.length === 0) {
    node.error("Resposta invalida da Open-Meteo.", msg);
    return null;
}

msg.meta.record_count = d.hourly.time.length;
return msg;

// Preserva a resposta original da Open-Meteo, tal como veio, em
// weather_raw_original. Upsert pela chave natural -> 1 doc por recolha
// (sem duplicados), registando a 1a e a ultima extracao.
const raw = msg.payload;

msg.payload = [
    { extraction_id: msg.extraction_id },
    {
        $set: {
            extraction_id: msg.extraction_id,
            source: "open_meteo",
            airport_code: "ATL",
            period: { start: "2025-01-01", end: "2025-01-31" },
            format: "json",
            endpoint: "https://archive-api.open-meteo.com/v1/archive",
            record_count: msg.meta.record_count,
            last_extracted_at: msg.batch_ts,
            payload: raw
        },
        $setOnInsert: { first_extracted_at: msg.batch_ts }
    },
    { upsert: true }
];
return msg;

// Regista a falha em etl_logs. Este ramo NUNCA apaga dados.
msg.payload = [{
    source: "open_meteo",
    flow: "meteorologia",
    extraction_id: msg.extraction_id || "open_meteo_ATL_2025-01",
    error: (msg.error && msg.error.message) ? msg.error.message : String(msg.error),
    at: new Date().toISOString()
}];
return msg;

// Prepara o pedido ao BTS (SEM apagar dados).
// O BTS pode demorar > 2 min a enviar os ~26 MB; o http request tem timeout
// por omissao de 120 s, pelo que se sobe aqui o limite para 10 min.
// O BTS aborta pedidos sem User-Agent de browser -> enviamos headers realistas.
msg.extraction_id = "bts_2025_1_ATL";
msg.batch_ts = new Date().toISOString();
msg.requestTimeout = 600000;
msg.headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
    "Accept": "*/*"
};
return msg;

flow.set("f3_retry", 0); // download OK -> reinicia contador de retries

// O no 'zip' (decompress) devolve um array de { filename, payload: Buffer }.
const files = msg.payload;

if (!Array.isArray(files)) {
    node.error("O no zip nao devolveu um array de ficheiros", msg);
    return null;
}

const csv = files.find(function (f) {
    return typeof f.filename === "string" && f.filename.toLowerCase().lastIndexOf(".csv") !== -1;
});

if (!csv) {
    node.error("Nao encontrei nenhum ficheiro .csv dentro do ZIP", msg);
    return null;
}

msg.zipFilename = csv.filename;
msg.payload = csv.payload; // Buffer do CSV
files.length = 0; // ajuda o garbage collector

return msg;

// Filtra as partidas de ATL em janeiro de 2025 e re-serializa um CSV enxuto.
const COLS = ["FlightDate", "Reporting_Airline", "Origin", "Dest", "CRSDepTime", "DepTime", "DepDelayMinutes", "Cancelled", "Diverted", "WeatherDelay"];

function parseLine(line) {
    const out = [];
    let cur = "";
    let inQ = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line.charAt(i);
        if (inQ) {
            if (ch === '"') {
                if (line.charAt(i + 1) === '"') { cur += '"'; i++; }
                else { inQ = false; }
            } else { cur += ch; }
        } else if (ch === '"') { inQ = true; }
        else if (ch === ',') { out.push(cur); cur = ""; }
        else { cur += ch; }
    }
    out.push(cur);
    return out;
}

let text = msg.payload.toString("utf8");
if (text.charCodeAt(0) === 0xFEFF) { text = text.slice(1); }
const lines = text.split("\n");
text = null;

const header = parseLine(lines[0]);
const idx = {};
for (let c = 0; c < COLS.length; c++) { idx[COLS[c]] = header.indexOf(COLS[c]); }
for (let c = 0; c < COLS.length; c++) {
    if (idx[COLS[c]] < 0) {
        node.error("Coluna ausente no CSV do BTS: " + COLS[c], msg);
        return null;
    }
}

const out = [COLS.join(",")];
let count = 0;
for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (!line) { continue; }
    const f = parseLine(line);
    if (f[idx.Origin] !== "ATL") { continue; }
    const fd = f[idx.FlightDate];
    if (!fd || fd.slice(0, 7) !== "2025-01") { continue; }
    const row = [];
    for (let c = 0; c < COLS.length; c++) {
        const v = f[idx[COLS[c]]];
        row.push(v === undefined ? "" : v);
    }
    out.push(row.join(","));
    count++;
}
lines.length = 0; // liberta o array de linhas antes de montar o documento

const now = new Date().toISOString();
const doc = {
    source: "bts_transtats",
    dataset: "On_Time_Reporting_Carrier_On_Time_Performance_1987_present_2025_1",
    airport_code: "ATL",
    month: "2025-01",
    format: "csv",
    extraction_id: msg.extraction_id || "bts_2025_1_ATL",
    columns: COLS,
    row_count: count,
    csv: out.join("\n"),
    ingested_at: now
};

msg.rowCount = count;
// Upsert pela chave natural -> exatamente 1 documento (sem duplicados).
// Nunca se apaga antes de confirmar o sucesso.
msg.payload = [
    { source: "bts_transtats", dataset: doc.dataset, airport_code: "ATL", month: "2025-01" },
    { $set: doc, $setOnInsert: { first_ingested_at: now } },
    { upsert: true }
];
return msg;

// O BTS aborta ligacoes de forma intermitente; tentamos de novo com espera.
// Limite de 5 tentativas para nao martelar o servidor.
var tent = (flow.get("f3_retry") || 0) + 1;

if (tent > 5) {
    flow.set("f3_retry", 0);
    node.warn("Download do BTS falhou 5 vezes seguidas. Desisto desta execucao.");
    return null;
}

flow.set("f3_retry", tent);
node.warn("Retry do download BTS #" + tent);

msg.headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
    "Accept": "*/*"
};
msg.requestTimeout = 600000;

return msg;

// Pedido ao OurAirports: headers realistas + timeout folgado (defensivo).
msg.headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
    "Accept": "*/*"
};
msg.requestTimeout = 120000;
return msg;

// Valida a resposta antes de qualquer escrita (nunca se perdem dados).
if (msg.statusCode !== 200 || typeof msg.payload !== "string" || msg.payload.length < 100) {
    node.error("Resposta invalida do OurAirports: nada foi alterado.", msg);
    return null;
}
return msg;

const rows = msg.payload;

if (!Array.isArray(rows) || rows.length === 0) {
    node.error("Sem registos para converter em XML", msg);
    return null;
}

// Mapeamento oficial das 14 colunas do OpenFlights
const fields = [
    "airport_id",
    "name",
    "city",
    "country",
    "iata_code",
    "icao_code",
    "latitude",
    "longitude",
    "altitude",
    "timezone",
    "dst",
    "tz_database_time_zone",
    "type",
    "source"
];

function esc(value) {
    if (value === null || value === undefined) return "";
    return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&apos;");
}

const out = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    "<airports>"
];

for (const row of rows) {
    // Aceita objetos com colunas nomeadas ou arrays posicionais.
    const values = Array.isArray(row)
        ? row
        : fields.map(field => row[field]);

    out.push("  <airport>");

    for (let i = 0; i < fields.length; i++) {
        out.push(
            "    <" + fields[i] + ">" +
            esc(values[i]) +
            "</" + fields[i] + ">"
        );
    }

    out.push("  </airport>");
}

out.push("</airports>");

msg.payload = out.join("\n");
msg.xml_bytes = Buffer.byteLength(msg.payload, "utf8");
msg.row_count = rows.length;
msg.columns = fields;

return msg;

// O XML (~56 MiB) excede o limite de 16 MiB por documento MongoDB, pelo que
// fica em ficheiro (/data/raw/airports.xml); no Mongo guardamos apenas os
// metadados de referencia. Upsert pela chave natural -> 1 doc, sem duplicados.
const now = new Date().toISOString();
msg.payload = [
    { source: "ourairports", format: "xml" },
    {
        $set: {
            source: "ourairports",
            dataset: "airports",
            format: "xml",
            derived_from: "csv",
            source_url: "https://raw.githubusercontent.com/jpatokal/openflights/master/data/airports.dat?utm_source=chatgpt.com",
            record_count: msg.row_count,
            columns: msg.columns,
            xml_bytes: msg.xml_bytes,
            storage: "file",
            path: "/data/raw/airports.xml",
            last_extracted_at: now
        },
        $setOnInsert: { first_extracted_at: now }
    },
    { upsert: true }
];
return msg;

// Regista a falha em etl_logs. Este ramo nunca apaga nem altera dados de origem.
msg.payload = [{
    source: "ourairports",
    flow: "aeroportos",
    error: (msg.error && msg.error.message) ? msg.error.message : String(msg.error),
    at: new Date().toISOString()
}];
return msg;
